import{_ as e,O as a,o as s,c as r,a as i,i as n,f as o}from"./chunks/framework.fmIt2z2h.js";const N=JSON.parse('{"title":"附录B　编号体系与术语总表","description":"","frontmatter":{"title":"附录B　编号体系与术语总表","xkChars":665,"xkLessons":{"app-b":{"title":"附录B　编号体系与术语总表","lead":"索引让你找到合同，不能替你完成合同；同字母、相邻编号和数量都不提供额外证据或权限。","explanation":["原文定位：第4318—4355行，原站定位本分部导语（无独立编号锚点）。本题切片及完整用户原稿均在source目录，可逐字回查。","短引文：“本表只作导航索引。”附录B回答去哪里找定义与合同，而不以一个前缀代替全文条件。数量是索引条目数量，不是经验成立数量；编号相邻不意味着推理依赖或成熟顺序。[T-main]","01｜D0—D3共4项，在第三部分定义结构对象、基本状态词、有效反馈与尺度变换。定义固定语言与合同，不独立证明现实对象符合它。[T-main]","02｜U01—U11共11项，是第三部分通用结构原语。原语用于组织对象描述，不是11条已验证普适因果定律。[T-main]","03｜G1—G4共4个经验问题族，第四部分通过G-instance建立具体检验；引用G编号只是指出问题族，不能跳过实例资格。[T-main]","04｜法1—法3共3条共同方法约束，在第四部分及附录C，分别管任务与表示、材料身份与支持范围、事实价值与行动资格。这里的“法”不是经验必然规律或现实法律授权。[T-main]","05｜F1—F6共6个条件形式命题，在第四部分及附录C，覆盖任务恢复、闭合、动作共同可行、组合保持、误差传播、任务族精化。结论依各自数学条件，不是社会案例因编号相同就自动成立。[T-main]","06｜E1—E5共5项认识论约束，在第四部分。方法约束可要求如何判断，不自行提供现实效应数据。[T-main]","07｜C1—C12共12项，第四部分的结果合同、机制命题与程序桥接。这个C命题前缀不同于九轴中的因果层次C；C12要按自身桥接合同用。[T-main]","08｜A/X/T/O/C/R/I/N/J为第五部分SP九轴，共9个轴，不能压成微观宏观一条线。J授权不可由其余轴范围推导；N拓扑与规范N1—N5也不同。[T-main]","09｜M01—M09共9个第五部分尺度变换算子。变换后的保持、损失与新增条件须核，算子名字不证明迁移有效。[T-main]","10｜CM-*共6个第六部分条件机制族：FEEDBACK、LEARNING、MAINTENANCE、LOAD、PHASE、SELECTION。族内分支各有合同，不能拿“学习”二字代替载体、时序或作用证据。[T-main]","11｜H1—H6共6项第七部分人类领域条款。具体哪些是经验实例、分类或规范边界，应查各条身份，不把它们统一叫作六条实证定律。[T-main]","12｜GC/GS/GE/CV/RS/IS/IM/IB共8个第七部分强类型标签：生成条件/主体/事件、承接载体、责任主体、失稳来源/机制/行为。原表称“三组不可混装的强类型”，但不意味着八个标签可混用；同一现实实体可能有不同角色，字段仍分开取证。[T-main]","13｜HV01—HV11共11项第七部分人类变量统一接口，附录A给完整卡。接口存在不表示某人的变量状态已实测，也不直接产生调整权。[T-main]","14｜S0—S6加X0记作7+1：第八部分七个人类状态原型加一条有序退场路径。7+1不是八阶段，X0不叫S7，编号不排价值等级。[T-main]","15｜IG1—IG7共7闸，是第十三部分唯一主流程；16｜SJ1—SJ8共8项强判断材料；17｜L1—L3共3个诊断档位。流程、强判断件和投入档位是不同维度，不能把它们排成一条连续流程。[T-main]","18｜TOOL-*共6项第十三部分正式工具：EVIDENCE-LEDGER、OPEN-ASSERTION、CLAIM-VALIDATION、FORECAST-REGISTRY、STRESS-TEST、AI-BOUNDARY。工具记录可以承载检查，不以表单齐全自证判断正确。[T-main]","19｜N1—N5共5项第十四部分规范选择运行时前提；20｜O1—O4共4项有限授权程序；21｜PF-1—PF-10共10项规范选择与选择记录接口。价值选择、授权程序和接口记录分开；规范N不同于拓扑N，程序O不同于组织尺度O。[T-main]","22｜T0—T4共5个第十五部分干涉层级；23｜APP-*共9个应用模块REL/FAM/ORG/PLT/INS/OPI/SPC/EMG/ULS。干涉层级不是经验置信度，应用名也不授予对应领域权限。[T-main]","24｜GOV-01—GOV-24共24条第十六部分治理条款。治理约束与应用模块互相参照，但索引并不替代每条适用条件和行动边界。[T-main]","贯穿记号也要逐项读：S*=<B,X,R,I,T,SP,K>是D0候选对象合同七字段，分别边界、状态变量、关系或转移约束、接口、时间窗、尺度剖面、同一性判据。这些局部字母不能直接按SP九轴同字母解释；S*里的R不是观察分辨率R，I不是影响范围I，X不是空间轴X。[T-main]","N0是零模型，不是N1—N5的零号规范；K*/F*是修复目标同一性及功能判据。G-instance、H-instance是具体检验实例，编号不等于已supported。F1—F6是形式命题编号；单独F/F*可能按局部定义为动力更新、功能判据或修复目标，不从同字母推同对象。[T-main]","最后的历史边界是实质提醒：G3只检验给定当前表示之外的历史条件增量。载体介导学习、累积、持续与跨期再生产按各机制合同核，不以G3正向支持为共同前提。查索引时不能因这些词都有时间就一律接G3。[T-main]","实际查阅顺序是先确定当前句子的命名空间、局部定义、对象与版本，再回到正文合同，最后查实例材料和允许结论。本附录没有外部经验断言；硬添一个历史个案会把“导航用法”与“理论验证”混淆，因此本题用明确人工命名冲突练习，不冒称历史案例。[T-main]"],"argumentSteps":["识别前缀及局部命名空间，查对应正文部分。","将编号数量与实例支持数量分开。","区分定义、形式、经验、规范、程序和工具身份。","逐次核S*与SP同字母、F/F*、N0/N1—N5的局部定义。","G3只接当前表示外增量，其他跨期合同各自检查。","引用正文条件和实例材料，不用索引替证。"],"distinctions":[{"leftTitle":"S*对象合同","leftText":"七字段组织候选对象。","rightTitle":"SP尺度画像","rightText":"九轴范围与分辨率，嵌在对象合同中。"},{"leftTitle":"F1—F6","leftText":"六个形式命题ID。","rightTitle":"F或F*","rightText":"局部动力或功能/目标记号。"},{"leftTitle":"N拓扑轴","leftText":"网络范围。","rightTitle":"N1—N5","rightText":"规范运行前提；N0另为零模型。"},{"leftTitle":"七原型加一路径","leftText":"S0—S6及X0。","rightTitle":"八阶段","rightText":"索引未给这种演化序列。"}],"boundaries":["教学反例：把S*中的X按SP的空间轴解释，读取了错误字段。","教学反例：见到X0便称第八成熟阶段，违背7+1的类型区分。","原文边界：不能因出现学习或跨期字样就一律要求G3正支持。","原文边界：导航表不替代正文定义合同及使用限制。"],"questions":["表中数量能当已验证理论数吗？","F*一定是F1—F6的某一项吗？","G3是所有跨期学习前提吗？","怎样避免同字母误读？"],"diagramPath":"/reading-assets/APP-B/figures/index-lookup.png","caseLinks":[],"caseNotes":[],"sourceRefs":[{"section":"app-b","start_line":4318,"end_line":4355,"startLine":4318,"endLine":4355}],"outputId":"app-b","sourceHash":"df579dbdbb68442b1781b066606c267761f0a1673fbd034ce93eeeb41641439f","teachingExamples":[{"title":"教学构造：同字母仍需局部定义","text":"人工记录写S*.R=角色间关系，SP.R=按周汇总分辨率。这不是同一R的矛盾赋值，而是对象合同与尺度画像的不同字段。若把前者填进后者，会同时丢掉关系和压缩损失。","assumptions":"两份记录和赋值均虚构，只演示命名空间。","boundary":"没有现实对象认定或因果结论。"},{"title":"教学构造：7+1的算术不能变阶段论","text":"索引包含7个S原型和1条X0路径，条目数可以算8，但类型仍是7+1。数量相加不产生第八状态，也不产生必须走完7个原型才能退出的条件。","assumptions":"只作集合计数解释，名称来自用户原文。","boundary":"不外推组织演化规律或退场授权。"}],"counterexamples":[{"identity":"constructed_boundary","text":"教学反例：把S*中的X按SP的空间轴解释，读取了错误字段。","effect":"限制本节的无条件延伸；不否定具有独立依据的有限判断。","sourceIds":["T-main"]},{"identity":"constructed_boundary","text":"教学反例：见到X0便称第八成熟阶段，违背7+1的类型区分。","effect":"限制本节的无条件延伸；不否定具有独立依据的有限判断。","sourceIds":["T-main"]},{"identity":"source_counterexample","text":"原文边界：不能因出现学习或跨期字样就一律要求G3正支持。","effect":"限制本节的无条件延伸；不否定具有独立依据的有限判断。","sourceIds":["T-main"]},{"identity":"source_counterexample","text":"原文边界：导航表不替代正文定义合同及使用限制。","effect":"限制本节的无条件延伸；不否定具有独立依据的有限判断。","sourceIds":["T-main"]}],"questionAnswers":[{"question":"表中数量能当已验证理论数吗？","answer":"不能，它们是索引条目数量，证据状态另查。","basis":"导航边界。"},{"question":"F*一定是F1—F6的某一项吗？","answer":"不一定，局部定义决定，不能仅按字母对应。","basis":"贯穿记号。"},{"question":"G3是所有跨期学习前提吗？","answer":"不是，它限定当前表示外历史增量，其他路线按各合同。","basis":"附录末段。"},{"question":"怎样避免同字母误读？","answer":"先标对象合同/尺度/规范/形式命题等命名空间，再读局部定义。","basis":"同名不等于同物。"}],"figures":[{"path":"/reading-assets/APP-B/figures/index-lookup.png","alt":"前缀查正文合同，再核实例证据与上限，数量不等于支持。","caption":"据附录B导航性质。"},{"path":"/reading-assets/APP-B/figures/index-names.png","alt":"S*与SP、F1—F6与F/F*、N0与N规范/网络、S与X0分开。","caption":"据附录B末段及编号表。"}],"diagramBrief":"两图展示索引使用路径和主要命名冲突；完整24行及贯穿记号均在正文逐项解释。","applicability":{"realCase":"not_applicable","diagram":"applicable","reason":"本节为用户理论内部编号与记号导航，不提出外部历史事实或经验效应；使用明示教学命名冲突练习，不为凑案例虚构历史。"},"openQuestions":["本索引不能代替各正文合同或现实实例的来源核查。"],"taskId":"APP-B","sources":[{"id":"T-main","title":"Xikari著《Xikari-条件结构与转化论》","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68；文本自述2026年10月","locator":"§app-b，第4318—4355行","claim_support":["全部24行索引、贯穿记号与G3边界。"],"limits":["支持当前稿的文本含义与明确限定的推理；不自行证明经验普遍性、实施效果或读者学习成效。"],"access_status":"read"}],"lecturePath":"/reading-assets/APP-B/lecture.md","sourcesPath":"/reading-assets/APP-B/sources.json","sourceSlicePath":"/reading-assets/APP-B/source/APP-B.md","supplementaryFiles":[],"diagramsPath":"/reading-assets/APP-B/diagrams.md"}}},"headers":[],"relativePath":"theory/appendix-b.md","filePath":"theory/appendix-b.md"}'),p={name:"theory/appendix-b.md"};function T(c,t,l,S,m,u){const d=a("SectionLesson");return s(),r("div",null,[t[0]||(t[0]=i('<div class="theory-source"><p><a id="part_18"></a></p><h1 id="part-title-18" tabindex="-1"><span class="xk-part">附录B<span class="xk-part__gap">　</span></span>编号体系与术语总表 <a class="header-anchor" href="#part-title-18" aria-label="Permalink to &quot;附录B　编号体系与术语总表 {#part-title-18}&quot;">​</a></h1><p>全书共使用下列编号体系。本表只作导航索引，各体系的定义、合同与使用边界以正文相应部分为准。</p><div class="xk-table"><table><thead><tr><th>前缀</th><th>含义</th><th>数量</th><th>定义所在</th></tr></thead><tbody><tr><td>D0-D3</td><td>定义层:结构对象、基本状态词、有效反馈、尺度变换</td><td>4</td><td>第三部分</td></tr><tr><td>U01-U11</td><td>通用结构原语</td><td>11</td><td>第三部分</td></tr><tr><td>G1-G4</td><td>经验问题族（经 G-instance 建立具体检验）</td><td>4</td><td>第四部分</td></tr><tr><td>法1—法3</td><td>共同方法约束：任务与表示、材料身份与支持范围、事实价值与行动资格</td><td>3</td><td>第四部分及附录C</td></tr><tr><td>F1-F6</td><td>条件形式命题：任务恢复、闭合、动作共同可行性、组合保持、误差传播与任务族精化</td><td>6</td><td>第四部分及附录C</td></tr><tr><td>E1-E5</td><td>认识论约束</td><td>5</td><td>第四部分</td></tr><tr><td>C1-C12</td><td>结果合同、机制命题与程序桥接</td><td>12</td><td>第四部分</td></tr><tr><td>A/X/T/O/C/R/I/N/J</td><td>九轴尺度画像 SP 的九个轴</td><td>9</td><td>第五部分</td></tr><tr><td>M01-M09</td><td>尺度变换算子</td><td>9</td><td>第五部分</td></tr><tr><td>CM-*</td><td>条件机制:FEEDBACK、LEARNING、MAINTENANCE、LOAD、PHASE、SELECTION</td><td>6</td><td>第六部分</td></tr><tr><td>H1-H6</td><td>人类领域条款</td><td>6</td><td>第七部分</td></tr><tr><td>GC/GS/GE/CV/RS/IS/IM/IB</td><td>三组不可混装的强类型(生成条件/主体/事件,承接载体,责任主体,失稳来源/机制/行为)</td><td>8</td><td>第七部分</td></tr><tr><td>HV01-HV11</td><td>人类变量统一接口(完整接口卡见附录 A)</td><td>11</td><td>第七部分</td></tr><tr><td>S0-S6、X0</td><td>人类状态原型与有序退场路径</td><td>7+1</td><td>第八部分</td></tr><tr><td>IG1-IG7</td><td>七闸:唯一主流程</td><td>7</td><td>第十三部分</td></tr><tr><td>SJ1-SJ8</td><td>强判断八件套</td><td>8</td><td>第十三部分</td></tr><tr><td>L1-L3</td><td>诊断档位</td><td>3</td><td>第十三部分</td></tr><tr><td>TOOL-*</td><td>六项正式工具(EVIDENCE-LEDGER、OPEN-ASSERTION、CLAIM-VALIDATION、FORECAST-REGISTRY、STRESS-TEST、AI-BOUNDARY)</td><td>6</td><td>第十三部分</td></tr><tr><td>N1-N5</td><td>规范选择的运行时前提登记</td><td>5</td><td>第十四部分</td></tr><tr><td>O1-O4</td><td>有限授权程序</td><td>4</td><td>第十四部分</td></tr><tr><td>PF-1-PF-10</td><td>规范选择与选择记录的接口</td><td>10</td><td>第十四部分</td></tr><tr><td>T0-T4</td><td>干涉层级</td><td>5</td><td>第十五部分</td></tr><tr><td>APP-*</td><td>应用模块(REL、FAM、ORG、PLT、INS、OPI、SPC、EMG、ULS)</td><td>9</td><td>第十五部分</td></tr><tr><td>GOV-01-GOV-24</td><td>治理条款</td><td>24</td><td>第十六部分</td></tr></tbody></table></div><p>另有若干贯穿全书的记号:S*=&lt;B,X,R,I,T,SP,K&gt; 为 D0 候选对象合同的七个字段(边界、状态变量、关系或转移约束、接口、时间窗、尺度剖面、同一性判据);N0 为零模型;K*/F* 为修复的目标同一性判据与功能判据;G-instance、H-instance 为经验问题族与人类条款的具体检验实例。均以正文首次定义处为准。</p><p>F1—F6是形式命题编号；单独的F及F*按局部定义可以分别表示动力更新、功能判据或修复目标，不凭字母相同推定同一对象。G3只检验给定当前表示之外的历史条件增量；载体介导的学习、累积、持续效应与跨期再生产依各自机制合同检验，不以G3获得正向支持作为共同前提。</p></div>',1)),n(d,{section:"app-b"}),t[1]||(t[1]=o("div",{class:"theory-source"},null,-1))])}const E=e(p,[["render",T]]);export{N as __pageData,E as default};
